#!/usr/bin/env python3
"""
Expand the 40 new blog posts (IDs 400 to 439) to a 1,200+ word minimum.

Each expanded post packs:
- Longer intro with 3+ stats inside the first 30%
- 6 to 8 question-shaped H2s with answer capsules
- Worked examples, named tools, comparison tables
- 4 to 6 external citations to named research
- FAQ block (auto-promoted to FAQPage JSON-LD)
- Related reading block at the end (re-asserted)

Replaces the content of each post in the WXR. Idempotent.
"""
import re
import sys
from pathlib import Path

WXR = Path(__file__).parent / "wp-content/themes/booming-venture/import/booming-venture-content.xml"

# ---------- helpers ----------
def tldr(t): return ('<!-- wp:group {"backgroundColor":"booming-50","style":{"border":{"radius":"0.75rem"},"spacing":{"padding":{"top":"1.25rem","right":"1.25rem","bottom":"1.25rem","left":"1.25rem"}}},"layout":{"type":"constrained"}} -->'
                     '<div class="wp-block-group has-booming-50-background-color has-background" style="border-radius:0.75rem;padding:1.25rem">'
                     '<!-- wp:paragraph {"fontSize":"sm","style":{"typography":{"fontWeight":"600","textTransform":"uppercase","letterSpacing":"0.08em"}}} -->'
                     '<p class="has-sm-font-size" style="font-weight:600;text-transform:uppercase;letter-spacing:0.08em">Key takeaways</p>'
                     '<!-- /wp:paragraph -->'
                     '<!-- wp:paragraph --><p>' + t + '</p><!-- /wp:paragraph -->'
                     '</div><!-- /wp:group -->')

def h2(t):  return f'<!-- wp:heading --><h2 class="wp-block-heading">{t}</h2><!-- /wp:heading -->'
def h3(t):  return f'<!-- wp:heading {{"level":3}} --><h3 class="wp-block-heading">{t}</h3><!-- /wp:heading -->'
def p(t):   return f'<!-- wp:paragraph --><p>{t}</p><!-- /wp:paragraph -->'
def cap(t): return f'<!-- wp:paragraph {{"className":"bv-capsule","style":{{"typography":{{"fontWeight":"500"}}}},"fontSize":"lg"}} --><p class="bv-capsule has-lg-font-size" style="font-weight:500">{t}</p><!-- /wp:paragraph -->'
def ul(items):
    li = "\n".join(f"<li>{i}</li>" for i in items)
    return f'<!-- wp:list --><ul class="wp-block-list">\n{li}\n</ul><!-- /wp:list -->'
def ol(items):
    li = "\n".join(f"<li>{i}</li>" for i in items)
    return f'<!-- wp:list {{"ordered":true}} --><ol class="wp-block-list">\n{li}\n</ol><!-- /wp:list -->'
def faq(items):
    out = [h2("Frequently asked questions")]
    for q, a in items:
        out.append(h3(q))
        out.append(p(a))
    return "\n".join(out)
def link(text, url): return f'<a href="{text and url}" rel="noopener" target="_blank">{text}</a>'  # noqa
def link(text, url): return f'<a href="{url}" rel="noopener" target="_blank">{text}</a>'
def ilink(text, slug): return f'<a href="/blog/{slug}/">{text}</a>'
def cta(label, url): return p(f'Want help applying this in your account? <a href="{url}">{label}</a>.')

# Related-reading block, three siblings plus two bridges per post.
def related(slug):
    items = RELATED.get(slug, [])
    if not items:
        return ""
    lis = "\n".join(f'<li><a href="/blog/{s}/">{t}</a></li>' for s, t in items)
    return ("<!-- bv-related-reading -->\n"
        '<!-- wp:group {"className":"bv-related","style":{"border":{"radius":"0.75rem","width":"1px","color":"var:preset|color|border"},"spacing":{"padding":{"top":"1.25rem","right":"1.5rem","bottom":"1.25rem","left":"1.5rem"},"margin":{"top":"var:preset|spacing|50"}}},"layout":{"type":"constrained"}} -->'
        '<div class="wp-block-group bv-related has-border-color" style="border-color:var(--wp--preset--color--border);border-width:1px;border-radius:0.75rem;margin-top:var(--wp--preset--spacing--50);padding:1.25rem 1.5rem">'
        '<!-- wp:heading {"level":3,"fontSize":"lg"} --><h3 class="wp-block-heading has-lg-font-size">Related reading</h3><!-- /wp:heading -->'
        f'<!-- wp:list --><ul class="wp-block-list">\n{lis}\n</ul><!-- /wp:list -->'
        '</div><!-- /wp:group -->')

