def build_related():
    for pillar_key, slugs in PILLAR.items():
        for s in slugs:
            siblings = [x for x in slugs if x != s][:3]
            bridges  = BRIDGES.get(s, [])[:2]
            chosen = siblings + bridges
            RELATED[s] = [(x, TITLE[x]) for x in chosen if x in TITLE]

