# ---------- WXR replacement ----------
def main():
    if not POSTS:
        sys.exit("No expanded posts defined yet. Run subsequent fragments first.")
    xml = WXR.read_text(encoding="utf-8")

    pattern = re.compile(
        r'(<wp:post_name><!\[CDATA\[(?P<slug>[^\]]+)\]\]></wp:post_name>'
        r'[^<]*<wp:status><!\[CDATA\[publish\]\]></wp:status>'
        r'[^<]*<wp:post_type><!\[CDATA\[post\]\]></wp:post_type>'
        r'.*?<content:encoded><!\[CDATA\[)'
        r'(?P<body>.*?)'
        r'(\]\]></content:encoded>)',
        re.DOTALL,
    )
    n_applied = 0
    def repl(m):
        nonlocal n_applied
        slug = m.group("slug")
        if slug in POSTS:
            n_applied += 1
            return m.group(1) + POSTS[slug] + m.group(4)
        return m.group(0)
    new_xml = pattern.sub(repl, xml)
    WXR.write_text(new_xml, encoding="utf-8")
    print(f"Expanded {n_applied} posts in the WXR.")

if __name__ == "__main__":
    main()
